//! Edge-case integration tests for band-point-range — generated by bug-hunter agent.
//!
//! Because ferrum-core is a cdylib crate, integration tests cannot link
//! against it directly (same constraint as bug_hunt_scale_layout.rs). These
//! tests reproduce the implementation formulas inline, verbatim, to pin the
//! numeric contracts of:
//!
//!   - `OrdinalScaleData` (scale/ordinal.rs) — the RENDER band model that
//!     Band/Point/Ordinal explicit ranges resolve into (GH #39 phase 2);
//!   - `BandScaleData` (scale/band.rs) — the pyclass compute facade;
//!   - `PointScaleData` (scale/point.rs) — the pyclass compute facade,
//!     including `reverse` (GH #65);
//!   - `band_point_pixel_range` / `ordinal_pixel_range`
//!     (render/scale_resolve/positional.rs) — the explicitness gates.
//!
//! Any divergence between these pinned formulas and the implementation will
//! surface as a regression when the corresponding implementation tests are
//! updated. Tests marked `// BUG:` assert the mathematically-correct expected
//! value and FAIL on the current formula, documenting a live defect (each is
//! mirrored by a Python test against the real pyclass in
//! tests/test_bug_hunt_band_point_range.py).

// =========================================================================
// OrdinalScaleData — verbatim from crates/ferrum-core/src/scale/ordinal.rs
// =========================================================================

#[derive(Debug, Clone, PartialEq)]
struct OrdinalScaleData {
    domain: Vec<String>,
    range: Vec<f64>,
    padding: f64,
}

impl OrdinalScaleData {
    fn layout(&self) -> (f64, f64, f64) {
        let r_lo = *self.range.first().unwrap();
        let r_hi = *self.range.last().unwrap();
        let n = self.domain.len() as f64;
        let step = (r_hi - r_lo) / n;
        let half_band = step.abs() * (1.0 - self.padding) / 2.0;
        let first_center = r_lo + step / 2.0;
        (first_center, step, half_band)
    }

    fn scale_str(&self, s: &str) -> f64 {
        let idx = match self.domain.iter().position(|c| c == s) {
            Some(i) => i,
            None => return f64::NAN,
        };
        let (first_center, step, _) = self.layout();
        first_center + (idx as f64) * step
    }

    fn invert_band(&self, y: f64) -> Option<String> {
        if y.is_nan() {
            return None;
        }
        let (first_center, step, half_band) = self.layout();
        if step == 0.0 {
            return None;
        }
        let raw = (y - first_center) / step;
        let idx = raw.round() as i64;
        if idx < 0 || idx as usize >= self.domain.len() {
            return None;
        }
        let center = first_center + (idx as f64) * step;
        if (y - center).abs() <= half_band {
            Some(self.domain[idx as usize].clone())
        } else {
            None
        }
    }

    /// Mirrors OrdinalScale::bandwidth (positive even when reversed).
    fn bandwidth(&self) -> f64 {
        if self.domain.is_empty() {
            return 0.0;
        }
        let r_lo = *self.range.first().unwrap();
        let r_hi = *self.range.last().unwrap();
        ((r_hi - r_lo) / self.domain.len() as f64).abs()
    }
}

fn ordinal(domain: &[&str], range: Vec<f64>, padding: f64) -> OrdinalScaleData {
    OrdinalScaleData {
        domain: domain.iter().map(|s| s.to_string()).collect(),
        range,
        padding,
    }
}

// =========================================================================
// BandScaleData — verbatim from crates/ferrum-core/src/scale/band.rs
// =========================================================================

#[derive(Debug, Clone, PartialEq)]
struct BandScaleData {
    domain: Vec<String>,
    padding_inner: f64,
    padding_outer: f64,
    align: f64,
}

impl BandScaleData {
    fn layout(&self, extent: f64) -> (f64, f64) {
        let n = self.domain.len() as f64;
        if n == 0.0 {
            return (0.0, 0.0);
        }
        let denom = (n - self.padding_inner + self.padding_outer * 2.0).max(1.0);
        let step = extent / denom;
        let bandwidth = (step * (1.0 - self.padding_inner)).abs();
        (bandwidth, step)
    }

    fn scale_str(&self, s: &str, range_lo: f64, range_hi: f64) -> f64 {
        let idx = match self.domain.iter().position(|c| c == s) {
            Some(i) => i,
            None => return f64::NAN,
        };
        let extent = range_hi - range_lo;
        let (_bandwidth, step) = self.layout(extent);
        let start = range_lo
            + self.padding_outer * step
            + self.align
                * (extent
                    - (self.domain.len() as f64 - self.padding_inner + self.padding_outer * 2.0)
                        * step)
                    .max(0.0);
        start + (idx as f64) * step + step * self.padding_inner / 2.0
    }
}

// =========================================================================
// PointScaleData — verbatim from crates/ferrum-core/src/scale/point.rs
// =========================================================================

#[derive(Debug, Clone, PartialEq)]
struct PointScaleData {
    domain: Vec<String>,
    padding: f64,
    align: f64,
    reverse: bool,
}

impl PointScaleData {
    fn scale_str(&self, s: &str, range_lo: f64, range_hi: f64) -> f64 {
        let idx = match self.domain.iter().position(|c| c == s) {
            Some(i) => i,
            None => return f64::NAN,
        };
        let n = self.domain.len();
        if n <= 1 {
            let center = (range_lo + range_hi) / 2.0;
            return center;
        }
        let extent = range_hi - range_lo;
        let denom = (n as f64 - 1.0) + self.padding * 2.0;
        let step = extent / denom;
        let start = range_lo + self.padding * step + self.align * (extent - denom * step).max(0.0);
        let pos = start + (idx as f64) * step;
        if self.reverse {
            range_hi - (pos - range_lo)
        } else {
            pos
        }
    }
}

fn point(domain: &[&str], padding: f64, align: f64, reverse: bool) -> PointScaleData {
    PointScaleData {
        domain: domain.iter().map(|s| s.to_string()).collect(),
        padding,
        align,
        reverse,
    }
}

// =========================================================================
// Explicitness gates — verbatim from render/scale_resolve/positional.rs
// =========================================================================

fn band_point_pixel_range(range: Option<&[f64]>, pr: (f64, f64)) -> (Vec<f64>, bool) {
    match range {
        Some(r) if r.len() >= 2 => (vec![r[0], r[1]], true),
        _ => (vec![pr.0, pr.1], false),
    }
}

/// Mirror of `ordinal_pixel_range` with `OrdinalRangeValue` reduced to
/// `Option<f64>` (Number = Some, Str = None), preserving the numbers() filter.
fn ordinal_pixel_range(range: Option<&[Option<f64>]>, pr: (f64, f64)) -> (Vec<f64>, bool) {
    match range {
        Some(values) => {
            let nums: Vec<f64> = values.iter().copied().flatten().collect();
            if nums.is_empty() {
                (vec![pr.0, pr.1], false)
            } else {
                let explicit = nums.len() >= 2;
                (nums, explicit)
            }
        }
        None => (vec![pr.0, pr.1], false),
    }
}

// =========================================================================
// OrdinalScaleData (render band model) — degenerate / signed-extent cases
// =========================================================================

/// Zero-width explicit range [150, 150]: step = 0, every center collapses to
/// 150, no NaN anywhere, bandwidth 0. Exercises the division `(r_hi - r_lo)/n`
/// with a zero numerator (a user-reachable state via BandScale(range=[c, c])).
#[test]
fn ordinal_zero_width_range_centers_collapse_finitely() {
    let s = ordinal(&["a", "b", "c"], vec![150.0, 150.0], 0.0);
    for cat in ["a", "b", "c"] {
        let p = s.scale_str(cat);
        assert!(p.is_finite(), "center for {cat} must be finite, got {p}");
        assert_eq!(p, 150.0, "all centers must collapse to the range pixel");
    }
    assert_eq!(s.bandwidth(), 0.0);
}

/// Zero-width range + invert: the `step == 0.0` guard must return None (not
/// divide by zero into a bogus index).
#[test]
fn ordinal_zero_width_range_invert_returns_none() {
    let s = ordinal(&["a", "b"], vec![150.0, 150.0], 0.0);
    assert_eq!(s.invert_band(150.0), None, "step==0 invert must refuse, not divide by 0");
    assert_eq!(s.invert_band(0.0), None);
}

/// Inverted explicit range [260, 40] (hi < lo): 4 categories, step = -55,
/// centers descend 232.5 / 177.5 / 122.5 / 67.5 — the signed-extent oracle
/// consumed by explicit_band_centers — and bandwidth stays positive (55).
#[test]
fn ordinal_inverted_range_descending_centers_positive_bandwidth() {
    let s = ordinal(&["a", "b", "c", "d"], vec![260.0, 40.0], 0.0);
    assert_eq!(s.scale_str("a"), 232.5);
    assert_eq!(s.scale_str("b"), 177.5);
    assert_eq!(s.scale_str("c"), 122.5);
    assert_eq!(s.scale_str("d"), 67.5);
    assert_eq!(s.bandwidth(), 55.0, "bandwidth must be |step| under a reversed range");
}

/// Inverted range + inner padding: invert(scale(cat)) round-trips for every
/// category. The half_band term uses step.abs(), so a negative step must not
/// make the acceptance window empty.
#[test]
fn ordinal_inverted_range_invert_round_trip_with_padding() {
    let s = ordinal(&["a", "b", "c", "d"], vec![260.0, 40.0], 0.4);
    for cat in ["a", "b", "c", "d"] {
        let y = s.scale_str(cat);
        assert_eq!(
            s.invert_band(y).as_deref(),
            Some(cat),
            "invert(scale({cat})) must round-trip under an inverted range"
        );
    }
}

/// Inverted range invert: a pixel just outside the band gap (between bands)
/// returns None even with the negative step (the |y - center| <= half_band
/// window must be evaluated symmetrically).
#[test]
fn ordinal_inverted_range_invert_rejects_gap_pixels() {
    // padding 0.5 → half_band = 55 * 0.5 / 2 = 13.75. Band "a" center 232.5,
    // band "b" center 177.5; midpoint 205.0 sits in the padding gap.
    let s = ordinal(&["a", "b", "c", "d"], vec![260.0, 40.0], 0.5);
    assert_eq!(s.invert_band(205.0), None, "gap pixel must not resolve to a category");
}

/// Single category over an explicit range: center = midpoint of the range
/// (step = extent, first_center = lo + extent/2).
#[test]
fn ordinal_single_category_explicit_range_center_is_midpoint() {
    let s = ordinal(&["only"], vec![40.0, 260.0], 0.0);
    assert_eq!(s.scale_str("only"), 150.0);
    assert_eq!(s.bandwidth(), 220.0);
    // And under the inverted form the midpoint is the same pixel.
    let inv = ordinal(&["only"], vec![260.0, 40.0], 0.0);
    assert_eq!(inv.scale_str("only"), 150.0);
}

/// Empty domain (0-row data resolved with an explicit range): step is
/// `extent / 0` = ±inf internally, but every public lookup stays safe —
/// scale_str returns NaN (category can't be found), invert returns None,
/// bandwidth returns 0. Pins that the inf never escapes.
#[test]
fn ordinal_empty_domain_lookups_are_contained() {
    let s = OrdinalScaleData { domain: Vec::new(), range: vec![40.0, 260.0], padding: 0.0 };
    assert!(s.scale_str("anything").is_nan());
    assert_eq!(s.bandwidth(), 0.0);
    // invert on the inf-step layout: raw = (y - inf)/inf = NaN; NaN.round()
    // as i64 saturates to 0; 0 >= domain.len()==0 → None. Must not panic.
    assert_eq!(s.invert_band(150.0), None);
    assert_eq!(s.invert_band(f64::NAN), None);
}

/// Extreme range magnitudes (1e300 span): centers stay finite for a small
/// domain (no overflow in `(r_hi - r_lo) / n` or `first_center + i * step`).
#[test]
fn ordinal_huge_range_no_overflow() {
    let s = ordinal(&["a", "b"], vec![-1e300, 1e300], 0.0);
    let a = s.scale_str("a");
    let b = s.scale_str("b");
    assert!(a.is_finite() && b.is_finite(), "centers must be finite: a={a}, b={b}");
    assert!(a < b);
    assert_eq!(a, -5e299);
    assert_eq!(b, 5e299);
}

// =========================================================================
// PointScaleData facade — reverse (GH #65) composition corners
// =========================================================================

/// reverse=true over an INVERTED range is a double reversal: every category
/// lands exactly where the forward scale over the forward range puts it.
#[test]
fn point_reverse_composed_with_inverted_range_equals_forward() {
    let fwd = point(&["a", "b", "c"], 0.0, 0.5, false);
    let dbl = point(&["a", "b", "c"], 0.0, 0.5, true);
    for cat in ["a", "b", "c"] {
        let forward = fwd.scale_str(cat, 0.0, 300.0);
        let double = dbl.scale_str(cat, 300.0, 0.0);
        assert!(
            (forward - double).abs() < 1e-9,
            "reverse over [300,0] must equal forward over [0,300] for {cat}: {forward} vs {double}"
        );
    }
}

/// Single category ignores reverse, padding, and align: always the range
/// midpoint (the n <= 1 early return).
#[test]
fn point_single_category_ignores_reverse_padding_align() {
    for reverse in [false, true] {
        for padding in [0.0, 0.5, 10.0] {
            for align in [0.0, 0.5, 1.0] {
                let s = point(&["x"], padding, align, reverse);
                let p = s.scale_str("x", 40.0, 260.0);
                assert_eq!(
                    p, 150.0,
                    "single category must sit at midpoint (reverse={reverse}, padding={padding}, align={align})"
                );
            }
        }
    }
}

/// Zero-extent range: every position collapses to the single pixel, with and
/// without reverse (reverse of a constant is the same constant).
#[test]
fn point_zero_extent_range_positions_collapse() {
    for reverse in [false, true] {
        let s = point(&["a", "b", "c"], 0.5, 0.5, reverse);
        for cat in ["a", "b", "c"] {
            let p = s.scale_str(cat, 100.0, 100.0);
            assert_eq!(p, 100.0, "zero-extent position for {cat} (reverse={reverse}) must be 100");
        }
    }
}

/// reverse endpoint oracle with padding: n=3, padding=0.5 over [0, 300] →
/// step=100, forward a/b/c at 50/150/250; reversed, a mirrors to 250.
/// (Mirror about the range midpoint, per the domain-reversal equivalence
/// documented in positional.rs.)
#[test]
fn point_reverse_with_padding_mirrors_about_midpoint() {
    let s = point(&["a", "b", "c"], 0.5, 0.5, true);
    assert!((s.scale_str("a", 0.0, 300.0) - 250.0).abs() < 1e-9);
    assert!((s.scale_str("b", 0.0, 300.0) - 150.0).abs() < 1e-9);
    assert!((s.scale_str("c", 0.0, 300.0) - 50.0).abs() < 1e-9);
}

/// Unknown category under reverse still returns NaN (the early return happens
/// before the reverse arithmetic — reverse of NaN would still be NaN, but the
/// lookup must not resolve).
#[test]
fn point_reverse_unknown_category_is_nan() {
    let s = point(&["a"], 0.5, 0.5, true);
    assert!(s.scale_str("zzz", 0.0, 300.0).is_nan());
}

// =========================================================================
// BandScaleData facade — denominator clamp, degenerate domains, sign
// =========================================================================

/// The d3 denominator clamp: n=1, padding_inner=0.9, padding_outer=0 gives
/// n - pi + 2*po = 0.1, clamped to 1.0 → step = extent, bandwidth = extent
/// * (1 - 0.9). Without the clamp step would be 10x the extent.
#[test]
fn band_denominator_clamps_below_one() {
    let s = BandScaleData {
        domain: vec!["a".into()],
        padding_inner: 0.9,
        padding_outer: 0.0,
        align: 0.5,
    };
    let (bw, step) = s.layout(200.0);
    assert!((step - 200.0).abs() < 1e-9, "denominator must clamp to 1.0; step={step}");
    assert!((bw - 20.0).abs() < 1e-9, "bandwidth = extent * (1 - pi); got {bw}");
}

/// Empty domain: layout early-returns (0, 0) and scale_str returns NaN — no
/// division by the n==0 denominator.
#[test]
fn band_empty_domain_layout_zero_and_nan_lookup() {
    let s = BandScaleData {
        domain: Vec::new(),
        padding_inner: 0.1,
        padding_outer: 0.1,
        align: 0.5,
    };
    assert_eq!(s.layout(300.0), (0.0, 0.0));
    assert!(s.scale_str("a", 0.0, 300.0).is_nan());
}

// Regression test (GH #69): BandScaleData::layout used to return a NEGATIVE
// bandwidth for an inverted range (extent < 0 → step < 0 → bandwidth =
// step * (1 - pi) < 0). The pyclass getter BandScale::bandwidth() shipped
// that sign to Python; d3 never reports a negative bandwidth and
// `cx - bandwidth/2` consumers would silently flip sides. Fixed by taking
// `.abs()` of the bandwidth (not the signed `step`, which still drives
// `scale_str`'s descending-position arithmetic). Mirrored by
// tests/test_bug_hunt_band_point_range.py::test_band_scale_bandwidth_non_negative_with_inverted_range.
#[test]
fn band_bandwidth_non_negative_for_inverted_range() {
    let s = BandScaleData {
        domain: vec!["a".into(), "b".into()],
        padding_inner: 0.0,
        padding_outer: 0.0,
        align: 0.5,
    };
    let (bw, _step) = s.layout(40.0 - 260.0); // extent as computed for range=[260, 40]
    assert!(bw >= 0.0, "bandwidth must be non-negative for an inverted range; got {bw}");
}

/// align leftover activation: the ONLY reachable leftover > 0 case is the
/// denominator clamp (denom_raw < 1). n=1, pi=0.5, po=0 over [0, 100]:
/// step = 100, leftover = 100 - 0.5*100 = 50. align=0 keeps position at
/// pi/2 * step = 25; align=1 shifts by the full leftover to 75.
#[test]
fn band_align_shifts_within_clamped_leftover() {
    let mk = |align: f64| BandScaleData {
        domain: vec!["a".into()],
        padding_inner: 0.5,
        padding_outer: 0.0,
        align,
    };
    let p0 = mk(0.0).scale_str("a", 0.0, 100.0);
    let p1 = mk(1.0).scale_str("a", 0.0, 100.0);
    assert!((p0 - 25.0).abs() < 1e-9, "align=0 position; got {p0}");
    assert!((p1 - 75.0).abs() < 1e-9, "align=1 position must shift by the leftover; got {p1}");
}

// =========================================================================
// Explicitness gates (positional.rs)
// =========================================================================

/// A wire range with MORE than 2 entries truncates to the first two and still
/// counts as explicit — matching the pyclass constructor's `[v[0], v[1]]`.
#[test]
fn band_point_gate_truncates_extra_entries_still_explicit() {
    let (r, explicit) = band_point_pixel_range(Some(&[40.0, 260.0, 500.0]), (0.0, 600.0));
    assert_eq!(r, vec![40.0, 260.0]);
    assert!(explicit);
}

/// Documents the validation gap the gate does NOT close: non-finite range
/// entries pass straight through, still marked explicit. The constructor-level
/// gap (no validate_finite for Band/Point ranges) is proven end-to-end by the
/// Python tests; this pins that the resolver gate is not the layer catching it.
#[test]
fn band_point_gate_passes_non_finite_entries_through() {
    let (r, explicit) = band_point_pixel_range(Some(&[f64::NAN, 260.0]), (0.0, 600.0));
    assert!(r[0].is_nan(), "gate does not filter NaN (documented gap)");
    assert_eq!(r[1], 260.0);
    assert!(explicit, "a NaN-carrying 2-entry range is still treated as explicit");
}

/// Ordinal gate: a single NUMERIC entry is passed through unchanged but NOT
/// marked explicit (explicit_band_extent needs 2 entries) — the documented
/// asymmetry vs band_point_pixel_range, which falls back to the panel extent.
#[test]
fn ordinal_gate_single_number_passthrough_not_explicit() {
    let (r, explicit) = ordinal_pixel_range(Some(&[Some(40.0)]), (0.0, 600.0));
    assert_eq!(r, vec![40.0], "single numeric entry passes through unchanged");
    assert!(!explicit, "1-entry range must not count as explicit");
}

/// Ordinal gate: an all-string (color) range has no numbers → the panel
/// extent fallback, not explicit.
#[test]
fn ordinal_gate_all_string_range_falls_back() {
    let (r, explicit) = ordinal_pixel_range(Some(&[None, None]), (0.0, 600.0));
    assert_eq!(r, vec![0.0, 600.0]);
    assert!(!explicit);
}

/// Ordinal gate: mixed [num, str, num] extracts both numbers and IS explicit —
/// the seam the Python mixed-range render test exercises end-to-end.
#[test]
fn ordinal_gate_mixed_range_extracts_numbers_explicit() {
    let (r, explicit) = ordinal_pixel_range(Some(&[Some(40.0), None, Some(260.0)]), (0.0, 600.0));
    assert_eq!(r, vec![40.0, 260.0]);
    assert!(explicit);
}

/// Both gates: empty ranges fall back to the panel extent, never explicit,
/// never panicking on `r[0]` indexing.
#[test]
fn gates_empty_range_falls_back_no_panic() {
    let empty: Vec<f64> = Vec::new();
    assert_eq!(band_point_pixel_range(Some(&empty), (5.0, 95.0)), (vec![5.0, 95.0], false));
    let empty_vals: Vec<Option<f64>> = Vec::new();
    assert_eq!(ordinal_pixel_range(Some(&empty_vals), (5.0, 95.0)), (vec![5.0, 95.0], false));
}

// =========================================================================
// Cross-model consistency: the resolver band model vs explicit ranges
// =========================================================================

/// The GH #39 phase-2 oracle re-derived by hand: domain [a, b, c, d] over an
/// explicit [40, 260] resolves via OrdinalScaleData to centers
/// 67.5 / 122.5 / 177.5 / 232.5 (step 55), and each center sits strictly
/// inside the range with half a step of margin.
#[test]
fn resolver_band_model_explicit_range_hand_computed_oracle() {
    let (range, explicit) = band_point_pixel_range(Some(&[40.0, 260.0]), (0.0, 600.0));
    assert!(explicit);
    let s = ordinal(&["a", "b", "c", "d"], range, 0.0);
    let centers: Vec<f64> = ["a", "b", "c", "d"].iter().map(|c| s.scale_str(c)).collect();
    assert_eq!(centers, vec![67.5, 122.5, 177.5, 232.5]);
    for c in centers {
        assert!(c > 40.0 && c < 260.0, "center {c} must sit strictly inside the range");
        assert!((c - 40.0) >= 27.5 - 1e-9, "half-step margin from the low edge");
        assert!((260.0 - c) >= 27.5 - 1e-9, "half-step margin from the high edge");
    }
}

/// GH #65 reverse in the resolver model is a domain reversal: reversing the
/// domain vector before OrdinalScaleData resolution mirrors every center
/// about the range midpoint — the equivalence documented in positional.rs.
#[test]
fn resolver_reverse_as_domain_reversal_mirrors_centers() {
    let fwd = ordinal(&["a", "b", "c", "d"], vec![40.0, 260.0], 0.0);
    let rev = ordinal(&["d", "c", "b", "a"], vec![40.0, 260.0], 0.0);
    let mid = (40.0 + 260.0) / 2.0;
    for cat in ["a", "b", "c", "d"] {
        let f = fwd.scale_str(cat);
        let r = rev.scale_str(cat);
        assert!(
            ((mid - f) - (r - mid)).abs() < 1e-9,
            "reversed center for {cat} must mirror about the midpoint: fwd={f}, rev={r}"
        );
    }
}
